import { writeTextAtomic } from "../core/fsx.ts";
import { ghopHome, initFile, toShellPath } from "../core/paths.ts";
import type { Shell } from "../history/source.ts";
import { POWERSHELL_INIT } from "./powershell-init.ts";

export const INIT_VERSION = 1;

const BASH = [
  "# ghop-init v1 (generated by `ghop init bash`; ghop rewrites this file when its version changes)",
  "if [[ $- == *i* && -z ${GHOP_DISABLE-} && -z ${CI-} && ${TERM-} != dumb ]]; then",
  "  __ghop_home='__ROOT__'",
  "  export GHOP_SHELL=bash",
  "  [[ -f \"$__ghop_home/managed/bash.sh\" ]] && source \"$__ghop_home/managed/bash.sh\"",
  "",
  "  ghop() {",
  "    command ghop \"$@\"",
  "    local __ghop_rc=$?",
  "    if [[ -f \"$__ghop_home/reload.bash.sh\" ]]; then",
  "      source \"$__ghop_home/reload.bash.sh\"",
  "      command rm -f \"$__ghop_home/reload.bash.sh\"",
  "    fi",
  "    return $__ghop_rc",
  "  }",
  "",
  "  __ghop_daily() {",
  "    command -v ghop >/dev/null 2>&1 || return 0",
  "    local today last=",
  "    printf -v today '%(%Y-%m-%d)T' -1",
  "    [[ -r \"$__ghop_home/daily.stamp\" ]] && IFS= read -r last < \"$__ghop_home/daily.stamp\"",
  "    [[ $today == \"$last\" ]] && return 0",
  "    (",
  "      umask 077",
  "      mkdir -p \"$__ghop_home/shell\"",
  "      alias -p > \"$__ghop_home/shell/bash.aliases\"",
  "      compgen -A function > \"$__ghop_home/shell/bash.functions\"",
  "      {",
  "        printf 'BASH_VERSION=%s\\n' \"$BASH_VERSION\"",
  "        printf 'HISTSIZE=%s\\n' \"${HISTSIZE-}\"",
  "        printf 'HISTFILESIZE=%s\\n' \"${HISTFILESIZE-}\"",
  "        printf 'HISTCONTROL=%s\\n' \"${HISTCONTROL-}\"",
  "        [[ -n ${HISTTIMEFORMAT+x} ]] && printf 'HISTTIMEFORMAT_SET=1\\n'",
  "        [[ ${PROMPT_COMMAND-} == *'history -a'* ]] && printf 'PROMPT_HISTORY_A=1\\n'",
  "        shopt -q histappend && printf 'OPT_histappend=1\\n'",
  "        shopt -q autocd && printf 'OPT_autocd=1\\n'",
  "        shopt -q cdspell && printf 'OPT_cdspell=1\\n'",
  "        shopt -q globstar && printf 'OPT_globstar=1\\n'",
  "        if [[ -o vi ]]; then printf 'KEYMAP=vi\\n'; else printf 'KEYMAP=emacs\\n'; fi",
  "        [[ -n ${STARSHIP_SHELL-} ]] && printf 'STARSHIP=1\\n'",
  "      } > \"$__ghop_home/shell/bash.info\"",
  "    ) 2>/dev/null",
  "    command ghop daily",
  "  }",
  "",
  "  __ghop_precmd() {",
  "    local __ghop_status=$?",
  "    if [[ -z ${__ghop_started-} ]]; then",
  "      __ghop_started=1",
  "      export GHOP_HISTFILE=\"${HISTFILE:-$HOME/.bash_history}\"",
  "      __ghop_daily",
  "    fi",
  "    [[ -f \"$__ghop_home/fresh.flag\" ]] && { command ghop notify 2>/dev/null || command rm -f \"$__ghop_home/fresh.flag\"; }",
  "    return $__ghop_status",
  "  }",
  "",
  "  if [[ -n ${PROMPT_COMMAND+x} && ${PROMPT_COMMAND@a} == *a* ]]; then",
  "    [[ \" ${PROMPT_COMMAND[*]} \" == *\" __ghop_precmd \"* ]] || PROMPT_COMMAND+=(__ghop_precmd)",
  "  elif [[ ${PROMPT_COMMAND-} != *__ghop_precmd* ]]; then",
  "    PROMPT_COMMAND=\"${PROMPT_COMMAND:+$PROMPT_COMMAND$'\\n'}__ghop_precmd\"",
  "  fi",
  "fi",
  "",
].join("\n");

const ZSH = [
  "# ghop-init v1 (generated by `ghop init zsh`; ghop rewrites this file when its version changes)",
  "if [[ -o interactive && -z ${GHOP_DISABLE-} && -z ${CI-} && ${TERM-} != dumb ]]; then",
  "  typeset -g __ghop_home='__ROOT__'",
  "  export GHOP_SHELL=zsh",
  "  [[ -f \"$__ghop_home/managed/zsh.sh\" ]] && source \"$__ghop_home/managed/zsh.sh\"",
  "",
  "  ghop() {",
  "    command ghop \"$@\"",
  "    local __ghop_rc=$?",
  "    if [[ -f \"$__ghop_home/reload.zsh.sh\" ]]; then",
  "      source \"$__ghop_home/reload.zsh.sh\"",
  "      command rm -f \"$__ghop_home/reload.zsh.sh\"",
  "    fi",
  "    return $__ghop_rc",
  "  }",
  "",
  "  __ghop_daily() {",
  "    command -v ghop >/dev/null 2>&1 || return 0",
  "    local today=${(%):-%D{%Y-%m-%d}} last=",
  "    [[ -r \"$__ghop_home/daily.stamp\" ]] && IFS= read -r last < \"$__ghop_home/daily.stamp\"",
  "    [[ $today == \"$last\" ]] && return 0",
  "    (",
  "      umask 077",
  "      mkdir -p \"$__ghop_home/shell\"",
  "      alias -L > \"$__ghop_home/shell/zsh.aliases\"",
  "      print -rl -- ${(k)functions} > \"$__ghop_home/shell/zsh.functions\"",
  "      __ghop_on=()",
  "      for __ghop_o in ${(k)options}; do [[ ${options[$__ghop_o]} == on ]] && __ghop_on+=($__ghop_o); done",
  "      {",
  "        print -r -- \"ZSH_VERSION=$ZSH_VERSION\"",
  "        print -r -- \"HISTSIZE=$HISTSIZE\"",
  "        print -r -- \"SAVEHIST=$SAVEHIST\"",
  "        print -r -- \"OPTIONS=${(j:,:)__ghop_on}\"",
  "        if [[ \"$(bindkey -lL main)\" == *viins* ]]; then print -r -- \"KEYMAP=vi\"; else print -r -- \"KEYMAP=emacs\"; fi",
  "        [[ -n ${ZSH-} && -f ${ZSH}/oh-my-zsh.sh ]] && print -r -- \"OMZ=1\"",
  "        [[ -n ${STARSHIP_SHELL-} ]] && print -r -- \"STARSHIP=1\"",
  "        (( ${+functions[p10k]} )) && print -r -- \"P10K=1\"",
  "      } > \"$__ghop_home/shell/zsh.info\"",
  "    ) 2>/dev/null",
  "    command ghop daily",
  "  }",
  "",
  "  __ghop_precmd() {",
  "    if [[ -z ${__ghop_started-} ]]; then",
  "      typeset -g __ghop_started=1",
  "      export GHOP_HISTFILE=\"${HISTFILE:-${ZDOTDIR:-$HOME}/.zsh_history}\"",
  "      __ghop_daily",
  "    fi",
  "    [[ -f \"$__ghop_home/fresh.flag\" ]] && { command ghop notify 2>/dev/null || command rm -f \"$__ghop_home/fresh.flag\"; }",
  "    return 0",
  "  }",
  "  autoload -Uz add-zsh-hook",
  "  add-zsh-hook precmd __ghop_precmd",
  "fi",
  "",
].join("\n");

export function renderInit(shell: Shell, rootShellPath: string): string {
  const template = shell === "bash" ? BASH : shell === "zsh" ? ZSH : POWERSHELL_INIT;
  return template.replace("__ROOT__", () => rootShellPath.replaceAll("'", shell === "powershell" ? "''" : "'\\''"));
}

export function writeInitFile(shell: Shell): void {
  writeTextAtomic(initFile(shell), (shell === "powershell" ? "\uFEFF" : "") + renderInit(shell, toShellPath(ghopHome(), shell)));
}
